style.css:
@-moz-document domain("google.com") {
/* Fundo escuro translúcido da página */
    body, html {
        background: rgba(18, 18, 18, 0.9) !important;
        color: #E0E0E0 !important;
        backdrop-filter: blur(10px);
    }

    /* Logo do Google com opacidade */
    #hplogo, .lnXdpd, .logo {
        filter: grayscale(100%) brightness(0.8) opacity(0.8);
    }

    /* Estiliza a barra de pesquisa com efeito glassmorphism */
    input[type="text"], input[type="search"] {
        background: rgba(51, 51, 51, 0.7) !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        color: #ffffff !important;
        padding: 12px !important;
        border-radius: 10px !important;
        font-size: 16px !important;
        backdrop-filter: blur(5px);
        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.2);
    }

    /* Botões de pesquisa com estilo de vidro */
    input[type="submit"], .RNmpXc {
        background: rgba(68, 68, 68, 0.7) !important;
        color: #ffffff !important;
        border: none !important;
        padding: 10px 20px !important;
        margin-top: 10px;
        border-radius: 10px !important;
        font-weight: bold;
        cursor: pointer;
        backdrop-filter: blur(5px);
        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.2);
        transition: background 0.3s ease;
    }

    /* Efeito de hover nos botões */
    input[type="submit"]:hover, .RNmpXc:hover {
        background: rgba(85, 85, 85, 0.8) !important;
    }

    /* Resultados da pesquisa com efeito de vidro */
    .g {
        background: rgba(30, 30, 30, 0.7) !important;
        padding: 20px !important;
        border-radius: 10px !important;
        margin-bottom: 15px !important;
        backdrop-filter: blur(5px);
        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.2);
    }

    /* Títulos dos resultados da pesquisa */
    h3, .LC20lb {
        color: #bb86fc !important;
        font-size: 18px !important;
    }

    /* URLs dos resultados da pesquisa */
    a {
        color: #8ab4f8 !important;
        text-decoration: none;
    }

    /* Links visitados */
    a:visited {
        color: #b39ddb !important;
    }

    /* Descrição dos resultados da pesquisa */
    .st, .IsZvec {
        color: #E0E0E0 !important;
        font-size: 14px !important;
    }

    /* Menu superior (Imagens, Notícias, etc.) com estilo glassmorphism */
    #top_nav {
        background: rgba(30, 30, 30, 0.7) !important;
        color: #E0E0E0 !important;
        border-bottom: 1px solid rgba(255, 255, 255, 0.2);
        backdrop-filter: blur(5px);
        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.2);
    }

    /* Links do menu superior */
    #top_nav a {
        color: #8ab4f8 !important;
    }

    /* Links ativos no menu superior */
    #top_nav .hdtbSel {
        color: #bb86fc !important;
        font-weight: bold;
    }

    /* Fundo do rodapé com efeito glassmorphism */
    #fbar {
        background: rgba(30, 30, 30, 0.7) !important;
        color: #E0E0E0 !important;
        backdrop-filter: blur(5px);
        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.2);
    }

    /* Links do rodapé */
    #fbar a {
        color: #8ab4f8 !important;
    }

    /* Efeito de hover em todos os links */
    a:hover {
        text-decoration: underline !important;
        color: #ffffff !important;
    }
}
